<?php require 'inc/bootstrap.php'; need('viewer'); if (me()['role']==='vendor') redirect('supply.php'); field_post();
$id = (int)($_GET['id'] ?? 0); $n = q("SELECT n.*,u.name creator FROM incidents n LEFT JOIN users u ON u.id=n.created_by WHERE n.id=?", [$id])->fetch(); if (!$n) redirect('incidents.php');
$title = $n['name']; $rows = field_rows(['incident'=>$id]);
$used = q("SELECT i.id,i.name,i.unit,t.type,SUM(t.qty) q FROM transactions t JOIN items i ON i.id=t.item_id WHERE t.incident_id=? AND t.type IN ('out','used','damaged','lost') AND ".scope_sql('i')." GROUP BY i.id,i.name,i.unit,t.type ORDER BY i.name", [$id])->fetchAll();
$log = q("SELECT t.*,i.name iname,u.name uname FROM transactions t JOIN items i ON i.id=t.item_id LEFT JOIN users u ON u.id=t.user_id WHERE t.incident_id=? AND ".scope_sql('i')." ORDER BY t.id DESC LIMIT 150", [$id])->fetchAll()
  ?: [];
$resv = can('checkout') ? res_list(['incident'=>$id,'status'=>'open']) : []; $label = ['out'=>'Used','used'=>'Used up','damaged'=>'Damaged','lost'=>'Lost'];
include 'inc/header.php'; ?>
<a href="incidents.php">&larr; Events / incidents</a>
<div class="d-flex justify-content-between align-items-start flex-wrap gap-2 mt-2 mb-3"><div><h1 class="h3 mb-0"><?=h($n['name'])?> <?=$n['status']==='open'?'<span class="badge text-bg-success fs-6">open</span>':'<span class="badge text-bg-secondary fs-6">closed</span>'?></h1>
<div class="text-muted"><?=h($n['kind'])?><?=$n['kind']&&$n['starts_on']?' · ':''?><?=h($n['starts_on'])?><?=$n['creator']?' · started by '.h($n['creator']):''?></div><?php if($n['notes']): ?><div class="small mt-1"><?=h($n['notes'])?></div><?php endif; ?></div>
<?php if(can('incidents_manage')): ?><form method="post" action="incidents.php"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="<?=$n['status']==='open'?'close':'reopen'?>"><button class="btn btn-outline-secondary btn-sm"><?=$n['status']==='open'?'Close event':'Reopen'?></button></form><?php endif; ?></div>
<?php if(can('checkout')): ?><div class="d-flex justify-content-between align-items-center mb-2"><h2 class="h5 mb-0">Reserved <span class="badge text-bg-secondary"><?=count($resv)?></span></h2><div class="d-flex gap-1 flex-wrap"><a class="btn btn-sm btn-outline-secondary" href="reservations.php?incident=<?=$id?>"><i class="bi bi-plus-lg"></i> Reserve gear</a>
<?php if($resv): ?><a class="btn btn-sm btn-outline-secondary" href="loan_sheet.php?incident=<?=$id?>&planned=1"><i class="bi bi-printer"></i> Reservation sheet</a><form method="post" action="reservations.php" class="d-inline"><?=csrf_field()?><input type="hidden" name="action" value="issue_all"><input type="hidden" name="incident_id" value="<?=$id?>"><input type="hidden" name="back" value="incident.php?id=<?=$id?>"><button class="btn btn-sm btn-primary" data-confirm="Issue everything reserved for this event now?">Issue all reserved</button></form><?php endif; ?></div></div>
<?php if($resv): ?><div class="card mb-4"><ul class="list-group list-group-flush small"><?php foreach($resv as $r): ?><li class="list-group-item d-flex justify-content-between"><span><a href="item_view.php?id=<?=$r['item_id']?>"><?=h($r['item'])?></a><?=$r['itype']==='returnable'?' &times; '.h(fmt_q($r['qty'])):''?> <span class="text-muted">&rarr; <?=h($r['borrower'])?></span></span><span class="text-nowrap"><?=h(res_range($r))?> <?=res_badge($r)?></span></li><?php endforeach; ?></ul></div><?php else: ?><div class="text-muted small mb-4">Nothing reserved for this event.</div><?php endif; ?><?php endif; ?>
<div class="d-flex justify-content-between align-items-center mb-2"><h2 class="h5 mb-0">Out now <span class="badge text-bg-secondary"><?=count($rows)?></span></h2>
<?php if($rows && can('checkout')): ?><div class="d-flex gap-1"><a class="btn btn-sm btn-outline-secondary" href="loan_sheet.php?incident=<?=$id?>"><i class="bi bi-printer"></i> Loan sheet</a><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="collect"><input type="hidden" name="incident_id" value="<?=$id?>"><button class="btn btn-sm btn-success" data-confirm="Mark everything still out for this event as returned in good condition?"><i class="bi bi-check2-all"></i> Collect everything</button></form></div><?php endif; ?></div>
<?=field_table($rows,'holder',true)?>
<?php if($used): ?><h2 class="h5 mt-4">Used, damaged or lost</h2><div class="card"><table class="table table-sm mb-0"><tbody><?php foreach($used as $u): ?><tr><td><a href="item_view.php?id=<?=$u['id']?>"><?=h($u['name'])?></a></td><td><?=h($label[$u['type']] ?? $u['type'])?></td><td class="text-end"><?=h(fmt_q($u['q']))?> <?=h($u['unit'])?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<?php if($log): ?><details class="mt-4"><summary class="small text-muted" style="cursor:pointer">Activity (<?=count($log)?>)</summary><div class="card mt-2"><div class="table-responsive"><table class="table table-sm small mb-0"><tbody><?php foreach($log as $t): ?><tr><td class="text-muted"><?=h(substr($t['created_at'],5,11))?></td><td><a href="item_view.php?id=<?=$t['item_id']?>"><?=h($t['iname'])?></a></td><td><?=h($t['type'])?> <?=$t['qty']!=0?h(fmt_q($t['qty'])):''?></td><td><?=h($t['uname'])?></td><td class="text-muted"><?=h($t['note'])?></td></tr><?php endforeach; ?></tbody></table></div></div></details><?php endif; ?>
<?php include 'inc/footer.php'; ?>
